/** Codes that anchor the national map view — a readable subset of the full table. */
const MAJOR_STATION_CODES = ["ADI","ADRA","AGC","AII","ANVT","ASN","ASR","BAM","BAY","BBS","BE","BINA","BJU","BKN","BKSC","BL","BNC","BPL","BPQ","BRC","BSB","BSL","BSP","BVI","BWN","BZA","CAN","CBE","CDG","CKP","CLT","CNB","CSMT","CTC","DD","DDU","DEE","DHN","DLI","DNR","DR","DURG","DWR","ED","ERS","ET","G","GAYA","GDR","GHY","GKP","GNT","GTL","GWL","HWH","HYB","JAM","JAT","JBP","JP","JSG","JU","JUC","KCG","KGP","KIR","KJM","KOAA","KOP","KOTA","KTE","KTYM","KUR","KYN","KZJ","LDH","LKO","LTT","MAO","MAS","MB","MDU","MFP","MLDT","MMCT","MMR","MRJ","MS","MTJ","MYS","NDLS","NED","NGP","NJP","NLR","NZM","PGT","PNBE","PNVL","PRYJ","PTK","PUNE","PURI","QLN","R","RJT","RJY","RKMP","RNC","ROU","RU","RXL","SA","SBC","SC","SDAH","SHM","SPJ","SRC","ST","STA","SUR","SVDK","TATA","TBM","TCR","TNA","TPJ","TPTY","TVC","UBL","UDZ","UMB","VAPI","VSKP","VZM","WL","YPR"];

/** @returns {{lat:number,lng:number,name:string,zone:string}|null} */
function getStationCoords(code) {
  if (!code) return null;
  return stationCoords[String(code).trim().toUpperCase()] || null;
}

/** Station master rows in the shape the frontend `Station` type expects. */
function listStations({ majorOnly = false } = {}) {
  const codes = majorOnly ? MAJOR_STATION_CODES : Object.keys(stationCoords);
  return codes.map((code) => {
    const entry = stationCoords[code];
    return { code, name: entry.name, position: { lat: entry.lat, lng: entry.lng }, zone: entry.zone };
  });
}

function searchStations(query, limit = 25) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return [];
  const results = [];
  for (const code of Object.keys(stationCoords)) {
    const entry = stationCoords[code];
    if (code.toLowerCase().includes(q) || entry.name.toLowerCase().includes(q)) {
      results.push({ code, name: entry.name, position: { lat: entry.lat, lng: entry.lng }, zone: entry.zone });
      if (results.length >= limit) break;
    }
  }
  return results;
}

module.exports = { stationCoords, MAJOR_STATION_CODES, getStationCoords, listStations, searchStations };
